prompt --application/shared_components/security/authentications/authenticate_user
begin
wwv_flow_imp_shared.create_authentication(
 p_id=>wwv_flow_imp.id(10623880555935831)
,p_name=>'authenticate_user'
,p_static_id=>'authenticate-user'
,p_scheme_type=>'NATIVE_CUSTOM'
,p_attributes=>wwv_flow_t_plugin_attributes(wwv_flow_t_varchar2(
  'authentication_function', 'authenticate_user',
  'enable_legacy_attributes', 'N')).to_clob
,p_plsql_code=>wwv_flow_string.join(wwv_flow_t_varchar2(
'FUNCTION authenticate_user (',
'    p_username IN VARCHAR2,',
'    p_password IN VARCHAR2',
') RETURN BOOLEAN',
'IS',
'    v_count NUMBER;',
'BEGIN',
'',
'    SELECT COUNT(*)',
'    INTO v_count',
'    FROM app_users',
'    WHERE LOWER(email) = LOWER(p_username)',
'    AND password_hash = STANDARD_HASH(p_password, ''SHA256'');',
'',
'    RETURN v_count = 1;',
'',
'EXCEPTION',
'    WHEN OTHERS THEN',
'        log_error(SQLCODE, SQLERRM, ''authenticate_user'', p_username);',
'        RETURN FALSE;',
'END;'))
,p_invalid_session_type=>'LOGIN'
,p_use_secure_cookie_yn=>'N'
,p_ras_mode=>0
,p_version_scn=>'SH256:gddXY0tLcNMw8DSvf5xlx0PeQAJCMnWG6R9R45QVFRc'
);
end;
