,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'SELECT ',
unistr('    ''\D83D\DCB7 Current Salary'' AS label,'),
unistr('    ''\00A3''||TO_CHAR(MAX(new_salary), ''FM999,999.00'') AS value'),
'FROM salary_history',
'WHERE employee_id = :P3_EMPLOYEE_ID',
'',
'UNION ALL',
'',
'SELECT',
unistr('    ''\D83D\DCC8 Total Raises'','),
'    TO_CHAR(COUNT(*))',
'FROM salary_history',
'WHERE employee_id = :P3_EMPLOYEE_ID',
'',
'UNION ALL',
'',
'SELECT',
unistr('    ''\D83D\DCB7 Biggest Raise'','),
unistr('    ''\00A3''|| TO_CHAR(MAX(new_salary - old_salary), ''FM999,999.00'')'),
'FROM salary_history',
'WHERE employee_id = :P3_EMPLOYEE_ID',
'',
'UNION ALL',
'',
'SELECT',
unistr('    ''\D83D\DCC8 Average Raise'','),
unistr('    ''\00A3''|| TO_CHAR(ROUND(AVG(new_salary - old_salary), 2), ''FM999,999.00'')'),
'FROM salary_history',
'WHERE employee_id = :P3_EMPLOYEE_ID;'))
